    "pp.help.q1": "Flouna सबसे अच्छा विकल्प कैसे चुनता है?",
    "pp.help.a1":
      "हम अंतिम प्रभावी क़ीमत (आइटम + डिलीवरी − ऑफ़र), डिलीवरी या पिकअप समय, और रेटिंग की तुलना करते हैं, फिर एक सबसे अच्छा विकल्प सुझाते हैं, और अगर आप स्पीड चाहें तो विकल्प भी।",
    "pp.help.q2": "मेरे ऑर्डर असल में कहाँ लगते हैं?",
    "pp.help.a2":
      "Flouna के अंदर ही, आप यहीं ऑर्डर और भुगतान करते हैं, और हम उसे पूरा करने वाले रेस्टोरेंट या मोबिलिटी पार्टनर तक पहुँचाते हैं। आप कभी ऐप से बाहर नहीं जाते।",
    "pp.help.q3": "रिफ़ंड कैसे काम करते हैं?",
    "pp.help.a3":
      "भुगतान Cashfree से सुरक्षित रूप से होते हैं। रद्द ऑर्डर का रिफ़ंड 5 to 7 कार्यदिवसों में आपके मूल भुगतान माध्यम में लौट आता है।",
    "pp.help.q4": "क्या मेरा डेटा सुरक्षित है?",
    "pp.help.a4":
      "हाँ, आपका पासवर्ड हैश करके रखा जाता है, सेशन सुरक्षित कुकीज़ पर चलते हैं, और हम आपका निजी डेटा कभी नहीं बेचते।",
