    "pp.help.q1": "Flouna सर्वोत्तम पर्याय कसे निवडते?",
    "pp.help.a1":
      "आम्ही अंतिम प्रभावी किंमत (आयटम + डिलिव्हरी − ऑफर्स), डिलिव्हरी किंवा पिकअप वेळ, आणि रेटिंगची तुलना करतो, मग एक सर्वोत्तम पर्याय सुचवतो, आणि वेगाच्या बाबतीत पर्यायही.",
