    "pp.help.a2":
      "Flouna मध्येच, तुम्ही इथेच ऑर्डर आणि पेमेंट करता, आणि आम्ही ती पूर्ण करणाऱ्या रेस्टॉरंट किंवा मोबिलिटी पार्टनरपर्यंत पोहोचवतो. तुम्ही कधी ॲपच्या बाहेर जात नाही.",
    "pp.help.q3": "रिफंड कसे काम करतात?",
    "pp.help.a3":
      "पेमेंट Cashfree द्वारे सुरक्षितपणे होते. रद्द केलेल्या ऑर्डरचा रिफंड 5 to 7 कामकाजी दिवसांत तुमच्या मूळ पेमेंट पद्धतीत परत येतो.",
    "pp.help.q4": "माझा डेटा सुरक्षित आहे का?",
