    "pp.about.blurb":
      "Flouna உங்கள் AI முடிவு இயந்திரம். ஆப்களை மாற்றி நீங்களே விலைகளை ஒப்பிடுவதற்குப் பதிலாக, Flouna-க்கு என்ன வேண்டும் என்று சொல்லுங்கள், அது உணவகங்கள் மற்றும் மொபிலிட்டி பார்ட்னர்களிடம் தேடுகிறது, சிறந்த சலுகைகளைப் பொருத்துகிறது, மதிப்புரைகளைப் படிக்கிறது, ஒரு தெளிவான பதிலை உங்களுக்குத் தருகிறது.",
