    "pp.rew.emptyNote":
      "ஒவ்வொரு ஆர்டரும் அடுத்த சிறந்த விருப்பத்தை விட நீங்கள் எவ்வளவு சேமித்தீர்கள் என்பதைக் காட்டுகிறது.",
