    "pp.help.title": "உதவி & ஆதரவு",
    "pp.help.intro": "என்ன தவறு நடந்தது என்று சொல்லுங்கள், பணம் திரும்ப மற்றும் கட்டணப் பிரச்சினைகளுக்கு முன்னுரிமை அளிக்கப்படும். பதில்கள் இங்கே தெரியும்.",
