    "pp.help.detailsPh": "முழு விவரங்களைக் கொடுங்கள், நாங்கள் விரைவாக சரிசெய்வோம்.",
    "pp.help.notAboutOrder": "குறிப்பிட்ட ஆர்டர் பற்றியது அல்ல",
