    "pp.help.catOrder": "ஆர்டர் சிக்கல்",
    "pp.help.catPayment": "கட்டணம்",
    "pp.help.catRefund": "பணம் திரும்ப",
    "pp.help.catAccount": "கணக்கு",
    "pp.help.catOther": "மற்றவை",
    "pp.help.stOpen": "திறந்துள்ளது",
    "pp.help.stInProgress": "நடைபெறுகிறது",
    "pp.help.stResolved": "தீர்க்கப்பட்டது",
    "pp.help.stClosed": "மூடப்பட்டது",
    "pp.help.q1": "Flouna சிறந்த விருப்பத்தை எப்படி தேர்வு செய்கிறது?",
    "pp.help.a1":
      "இறுதி செயல்படு விலை (பொருள் + டெலிவரி − சலுகைகள்), டெலிவரி அல்லது பிக்கப் நேரம், மற்றும் மதிப்பீடுகளை ஒப்பிடுகிறோம், பிறகு ஒரு சிறந்த விருப்பத்தைப் பரிந்துரைக்கிறோம், வேகத்திற்கான மாற்று விருப்பங்களும் உண்டு.",
    "pp.help.q2": "என் ஆர்டர்கள் உண்மையில் எங்கே பதிவாகின்றன?",
    "pp.help.a2":
      "Flouna-ல், நீங்கள் இங்கேயே ஆர்டர் செய்து பணம் செலுத்துகிறீர்கள், நாங்கள் அதை நிறைவேற்றும் உணவகம் அல்லது மொபிலிட்டி பார்ட்னருக்கு அனுப்புகிறோம். நீங்கள் ஆப்பை விட்டு வெளியே செல்ல வேண்டியதில்லை.",
    "pp.help.q3": "பணம் திரும்பப் பெறுவது எப்படி?",
    "pp.help.a3":
      "கட்டணங்கள் Cashfree மூலம் பாதுகாப்பாக செயலாக்கப்படுகின்றன. ரத்து செய்யப்பட்ட ஆர்டர்களுக்கான பணம் 5 to 7 வணிக நாட்களில் உங்கள் அசல் கட்டண முறைக்குத் திரும்பும்.",
    "pp.help.q4": "என் தரவு பாதுகாப்பானதா?",
    "pp.help.a4":
      "ஆம், உங்கள் கடவுச்சொல் ஹாஷ் செய்து சேமிக்கப்படுகிறது, அமர்வுகள் பாதுகாப்பான குக்கீகளில் இயங்குகின்றன, நாங்கள் உங்கள் தனிப்பட்ட தரவை ஒருபோதும் விற்க மாட்டோம்.",
    "landing.headline1": "தேடுவதை நிறுத்துங்கள்",
    "landing.headline2": "முடிவு செய்யுங்கள்",
    "landing.blurb":
      "Flouna உங்கள் AI முடிவு இயந்திரம், உணவு, ரைடுகள் மற்றும் மேலும், ஒரே இடத்தில் சிறந்த விருப்பத்தைக் கண்டுபிடிக்கிறது. ஆப்கள் மாற்ற வேண்டாம், முடிவிலா ஒப்பீடுகள் வேண்டாம். அறிவார்ந்த தேர்வு, உடனடியாக.",
