    "pp.help.q1": "Flouna ఉత్తమ ఎంపికను ఎలా ఎంచుకుంటుంది?",
    "pp.help.a1":
      "తుది ప్రభావ ధర (వస్తువు + డెలివరీ − ఆఫర్లు), డెలివరీ/పికప్ సమయం, రేటింగ్‌లను పోల్చి, ఒకే ఉత్తమ ఎంపికను సిఫారసు చేస్తాం, వేగం కావాలంటే ప్రత్యామ్నాయాలూ చూపిస్తాం.",
    "pp.help.q2": "నా ఆర్డర్లు అసలు ఎక్కడ నమోదవుతాయి?",
    "pp.help.a2":
      "Flouna లోపలే, మీరు ఇక్కడే ఆర్డర్ చేసి చెల్లిస్తారు; దాన్ని నెరవేర్చే రెస్టారెంట్ లేదా మొబిలిటీ భాగస్వామికి మేము చేరుస్తాం. మీరు యాప్ నుంచి బయటికి వెళ్లరు.",
    "pp.help.q3": "రీఫండ్‌లు ఎలా పనిచేస్తాయి?",
    "pp.help.a3":
      "చెల్లింపులు Cashfree ద్వారా సురక్షితంగా జరుగుతాయి. రద్దయిన ఆర్డర్ల రీఫండ్ 5 to 7 పనిదినాల్లో మీ అసలు చెల్లింపు మార్గానికి తిరిగి వస్తుంది.",
    "pp.help.q4": "నా డేటా సురక్షితమేనా?",
    "pp.help.a4":
      "అవును, మీ పాస్‌వర్డ్ హ్యాష్ చేసి నిల్వ అవుతుంది, సెషన్లు సురక్షిత కుకీలపై నడుస్తాయి, మీ వ్యక్తిగత డేటాను మేము ఎప్పుడూ అమ్మం.",
    "landing.headline1": "వెతకడం ఆపండి",
